/** Item rows per page (n8n Out keeps pageSize + 1 nav row fixed). */
const COURSE_PAGE_SIZE = 2;
const LECTURE_PAGE_SIZE = 4;

function coursesKeyboard(courses) {
  return inlineKeyboardRows(
