function pageCaption(prefix, offset, pageSize, total) {
  if (!total) return prefix;
  if (total <= pageSize) return prefix;
  const from = offset + 1;
  const to = Math.min(offset + pageSize, total);
  return `${prefix} (${from}–${to} из ${total})`;
